/*
 * matcher_glue.c — the public MatchingEngine API (c/include/matching_engine.h)
 * over the generated matcher (c/gen/matcher.c), so the existing C tests and
 * benchmark drive it unchanged. MatchingEngine_CheckInvariants comes from the
 * handwritten engine, compiled with its matcher entry points renamed (Makefile).
 */
#include "../include/matching_engine.h"
#include "engine_db_adapter.h"

#include <stdint.h>

/* Generated by lean/Matcher/Program.lean. */
uint64_t gen_process_order(uint64_t id, uint64_t account, uint64_t side, uint64_t otype,
                           uint64_t stp, uint64_t price, uint64_t qty);
uint64_t gen_cancel_order(uint64_t id);

#ifndef ME_GLUE_CAPACITY
#define ME_GLUE_CAPACITY UINT64_C(1000000)
#endif

enum { GEN_ACCEPTED = 0, GEN_CANCELLED = 1 };

void MatchingEngine_Init(MatchingEngine *engine, TradeCallback cb, void *user_data) {
    ME_adapter_init(ME_GLUE_CAPACITY);
    if (engine) {
        engine->total_trades = 0;
        engine->total_volume = 0;
        engine->on_trade = cb;
        engine->user_data = user_data;
    }
}

bool MatchingEngine_ProcessOrder(MatchingEngine *engine, const OrderRequest *req) {
    if (!req) return false;
    uint64_t code = gen_process_order(req->id, req->account_id, req->side, req->order_type,
                                      req->stp_mode, req->price, req->qty);
    uint64_t n = ME_adapter_trade_count();
    for (uint64_t i = 0; i < n; ++i) {
        TradeEvent t;
        ME_adapter_trade_get(i, &t.passive_id, &t.aggressor_id, &t.price, &t.qty);
        if (engine) {
            engine->total_trades++;
            engine->total_volume += t.qty;
            if (engine->on_trade) engine->on_trade(&t, engine->user_data);
        }
    }
    return code == GEN_ACCEPTED;
}

bool MatchingEngine_CancelOrder(MatchingEngine *engine, uint64_t order_id) {
    (void)engine;
    return gen_cancel_order(order_id) == GEN_CANCELLED;
}
